size(8.5cm); pair A = dir(140); pair B = dir(210); pair C = dir (330); filldraw(A--B--C--cycle, invisible, grey); dot(" $A$ ", A, A); dot(" $B$ ", B, B); dot(" $C$ ", C, C); draw(incircle(A,B,C), black+1); pair D = foot(A,B,C); dot(" $P^+$ ", D, dir(-45), brown); draw(A--D, brown); pair I = incenter(A,B,C); pair O = circumcenter(A,B,C);
real a = abs(B-C); real b = abs(C-A); real c = abs(A-B); real s = 0.5*(a+b+c); real ha = abs(A-D); real k = ((s-a)**3) / (s*ha*abs(A-I)**2);
pair PA = k*b*c/2*dir(O-A)+A; dot(" $P_A$ ", PA, dir(255), blue); draw(CP(PA,A), lightblue); pair P = Drawing("P", 2*PA-A, dir(180));
pair QA = PA + dir(PA-A)*( (s-a)*a**2 / (a*b*c) ); dot(" $Q_A$ ", QA, dir(-80)*1.4, blue); draw(CP(QA,A), lightblue); pair Q = Drawing("Q", 2*QA-A, dir(-70));
draw(unitcircle, grey); draw(A--Q); real r = abs(I-foot(I,B,C)); Drawing("I", I, dir(90)); pair X = I + dir(O-A)*r; pair P1 = foot(X,P,Q); draw(Line(X,P1,2.5), red, Arrows(TeXHead)); dot(" $P^\ast$ ", P1, dir(5), red); draw(CP(A, foot(I,A,B)), dashed+deepgreen);
pair Q2 = D+dir(A-D)*2*r; dot(" $Q^+$ ", Q2, dir(145), brown); draw(Q2--(I+r*dir(90)), brown);
[/asy]
Now we can compute all the lengths directly.  We have that \[ AP_A = \frac{1}{2} AP = \frac{(s-a)^2}{2AP^+} = \frac{1}{2} (s-a)^2 \cdot \frac{1}{h_a} \] and \[ AQ_A = \frac{1}{2} AQ = \frac{(s-a)^2}{2AQ^+} = \frac{1}{2} (s-a)^2 \cdot \frac{1}{h_a-2r} \] where  $h_a = \frac{2K}{a}$  is the length of the  $A$ -altitude, with  $K$  the area of  $ABC$  as usual. Now it follows that \[ P_AQ_A = \frac{1}{2} (s-a)^2 \left( \frac{2r}{h_a(h_a-2r)} \right). \] This can be simplified, as \[ h_a - 2r = \frac{2K}{a} - \frac{2K}{s} = 2K \cdot \frac{s-a}{as}. \] Hence \[ P_AQ_A = \frac{a^2rs(s-a)}{4K^2} = \frac{a^2(s-a)}{4K}. \] Hence, the problem is just asking us to show that \[ a^2b^2c^2(s-a)(s-b)(s-c) \le 8 (RK)^3. \] Using  $abc=4RK$  and  $(s-a)(s-b)(s-c) = \frac 1s K^2 = rK$ , we find that this becomes \[ 2(s-a)(s-b)(s-c) \le RK \iff 2r \le R \] which follows immediately from  $IO^2=R(R-2r)$ . Alternatively, one may rewrite this as Schur's Inequality in the form \[ abc \ge (-a+b+c)(a-b+c)(a+b-c). \]

