        {(1, 1), E},
        {(3, 1), E},
        {(5, 1), N},
        {(1, 3), N},
        {(5, 3), W},
        {(1, 5), E},
        {(3, 5), E},
        {(5, 5), E}};
    for (int i = 0; i < data.length; ++i) {
        domino(data[i][0], data[i][1]);
