B_P = (3 - 2*h/3, h/3),
C_P = (3- 2*h/3, 3- 2*h/3),
D_P = (h/3, 3- 2*h/3),
A_Q = (2*h/3,2*h/3),
B_Q = (3 - h/3, 2*h/3),
C_Q = (3- h/3, 3- h/3),
D_Q = (2*h/3, 3- h/3);
draw(A_P -- B_P -- C_P -- D_P -- cycle);
