label(" $B'_Q$ ", B_Q, SE);
label(" $C'_P$ ", C_P, NE);
label(" $C'_Q$ ", C_Q, NE);
label(" $D'_P$ ", D_P, NW);
label(" $D'_Q$ ", D_Q, NW);
