vector<int> simulate(vector<int> mangoEaters)
{
	vector<int> possibleMovers;

	for (size_t i = 0; i < mangoEaters.size(); i++)
	{
		if (mangoEaters[i] > 1) { possibleMovers.push_back(i); }
	}

	while (possibleMovers.size() > 0)
	{
		int m = rand() % 2, j = rand() % possibleMovers.size(), k = possibleMovers[j];

		if (mangoEaters[k] >= 3 && m == 0)
		{
			mangoEaters[k] -= 3;

			if (k == 0) { mangoEaters[mangoEaters.size() - 1] += 2; }
			else { mangoEaters[k - 1] += 2; }

			if (k == mangoEaters.size() - 1) { mangoEaters[0] += 1; }
			else { mangoEaters[k + 1] += 1; }
		}
		else if (mangoEaters[k] >= 2)
		{
			mangoEaters[k] -= 2;

			if (k == mangoEaters.size() - 1) { mangoEaters[0] += 1; }
			else { mangoEaters[k + 1] += 1; }
		}

		for (size_t i = 0; i < possibleMovers.size(); i++)
		{
			int l = possibleMovers[i];

			if (mangoEaters[l] < 2) { possibleMovers.erase(possibleMovers.begin() + i); }
		}

		for (size_t i = 0; i < mangoEaters.size(); i++)
		{
			if (mangoEaters[i] > 1)
			{
				possibleMovers.push_back(i);
			}
		}
	}

	return mangoEaters;
}

