draw(arc((3/2, 1-3*sqrt(3)/2), 3, 120, 60));
draw(arc((2*(3/2), 2*(1-3*sqrt(3)/2)-1), 2*3, 120, 60), linewidth(2));
draw(arc((3*(3/2), 3*(1-3*sqrt(3)/2)-2), 3*3, 120, 60));
draw(arc((4*(3/2), 4*(1-3*sqrt(3)/2)-3), 4*3, 120, 60), linewidth(2));
draw(arc((5*(3/2), 5*(1-3*sqrt(3)/2)-4), 5*3, 120, 60));
