If anyone is interested, here's the java program I created trying to solve this problem (still did not solve it tho).
It partitions each odd integer smaller than  $2^n$  into groups based on their inclusion in cycles
[java]
import java.util.*;
public class R2P5Stuff {
	static final long multiplier = (long) Math.pow(5, 10);
	static final long enumerator = (long) Math.pow(2, 10);
	//change the second argument of both variables to any integer you like
	public static void main(String[] args) {
		long yeet = 0;
		fullPrintout();
		fullPrintoutLengths();
		while (yeet != -1) {
			long a1 = 0;
			Scanner scan = new Scanner(System.in);
			System.out.print("Enter a1: ");
			a1 = scan.nextInt();

			for (long i = 0; i < 60; i++) {
				System.out.print(a1 + ", ");
				a1 = process(a1);
			}
			System.out.println();
		}

	}

	public static long process (long n) {
		return toBinary2(toBinary1(multiplier * n));
	}

	public static long toBinary1 (long n) {
		ArrayList <Long> bigChungus = new <Long> ArrayList ();
		while (n > 0) {
			if ((n % 10) % 2 == 0) {
				bigChungus.add(n - (n%10));
			}
			else {
				bigChungus.add(n - (n%10) + 1);
			}
			n /= 10;

		}
		String minecraft = "";
		for (int i = bigChungus.size() - 1; i >= 0; i--) {
			minecraft += bigChungus.get(i) % 10;
		}
		return Long.parseLong(minecraft);

	}

	public static long toBinary2 (long bn) {
		String s = Long.toString(bn);
		return Long.parseLong(s, 2);
	}

	public static void fullPrintout () {
		 ArrayList <ArrayList <Long>> keanuReeves = new <ArrayList <Long>> ArrayList ();
		 for (long i = 1; i < enumerator; i+=2) {
			 int repeated = 0;
			 ArrayList <Long> patternForI = new <Long> ArrayList ();
			 long initial = i;
			 do {
				 patternForI.add(i);
				 if (i < initial) {
					 repeated = 1;
				 }
				 i = process(i);
			 } while (i != initial);
			 if (repeated == 0) {
				 keanuReeves.add(patternForI);
			 }
 		 }
		 bubbleSortArrayListsBasedOnLength (keanuReeves);
		 for (ArrayList <Long> s : keanuReeves) {
			 System.out.println(s);
		 }
	}

	public static void fullPrintoutLengths () {
		 ArrayList <ArrayList <Long>> keanuReeves = new <ArrayList <Long>> ArrayList ();
		 for (long i = 1; i < enumerator; i+=2) {
			 int repeated = 0;
			 ArrayList <Long> patternForI = new <Long> ArrayList ();
			 long initial = i;
			 do {
				 patternForI.add(i);
				 if (i < initial) {
					 repeated = 1;
				 }
				 i = process(i);
			 } while (i != initial);
			 if (repeated == 0) {
				 keanuReeves.add(patternForI);
			 }
		 }
		 bubbleSortArrayListsBasedOnLength (keanuReeves);
		 for (ArrayList <Long> s : keanuReeves) {
			 System.out.print(s.size() + " ");
		 }
	}

	public static void bubbleSortArrayListsBasedOnLength (ArrayList <ArrayList <Long>> al) {
		int n = al.size();
		for (int i = 0; i < n-1; i++) {
			for (int j = 0; j < n-i-1; j++) {
				if (al.get(j).size() < al.get(j+1).size()) {
					ArrayList <Long> tmpList = new ArrayList <Long> (al.get(j));
					al.get(j).clear();
					al.get(j).addAll(al.get(j+1));
					al.get(j+1).clear();
					al.get(j+1).addAll(tmpList);
				}
			}
		}
	}

}

[/java]

