<details><summary>Code</summary>```
//runs in just 0.03 seconds
#include <bits/stdc++.h>
using namespace std;
using vi = vector<int>;
#define pb push_back
#define rep(i, a, b) for(int i = a; i < (b); ++i)
#define trav(a, x) for(auto& a : x)
using pii = pair<int,int>;
#define f first
#define s second
#define mp make_pair

int grid[5][5];
vi pool;
int placed = 0;
void dfs(int x, int y) {
    //out of bounds
    if(x > 4 || x < 0 || y > 4 || y < 0) return;
    //black square
    if(x == 1 && (y == 1 || y == 2) || x == 3 && (y == 2 || y == 3)) return;
    //visited
    if(grid[x][y] >= 0) return;

    pii adj[4] = {{x-1, y}, {x+1, y}, {x, y-1}, {x, y+1}};
    //tries every prime left in the pool
    rep(i, 0, pool.size()) {
        int p = pool[i];
        //digit requirements
        if(y == 0 && (x == 0 || x == 2) || x == 4 && y == 4)
            if(!(p % 10 == 3 || p/10 == 3)) continue;
        if(y == 4 && (x == 2 || x == 3) || x == 1 && y == 0)
            if(!(p % 10 == 1 || p/10 == 1)) continue;
        if(y == 2 && (x == 2 || x == 0))
            if(!(p % 10 == 9 || p/10 == 9)) continue;
        if(y == 0 && (x == 3))
            if(!(p % 10 == 2 || p/10 == 2)) continue;
        if(y == 4 && (x == 1))
            if(!(p % 10 == 4 || p/10 == 4)) continue;
        if(y == 2 && (x == 4))
            if(!(p % 10 == 5 || p/10 == 5)) continue;
        //checks adjacent squares (must share digit)
        bool works = true;
        trav(a, adj) {
            if(a.f > 4 || a.f < 0 || a.s > 4 || a.s < 0) continue;
            if(grid[a.f][a.s] >= 0 && grid[a.f][a.s] % 10 != p % 10 && grid[a.f][a.s] / 10 != p/10) {
                works = false;
                break;
            }
        }
        if(!works) continue;
        //fills, recursively fills adjacent squares
        grid[x][y] = p;
        pool[i] = pool[pool.size() - 1];
        pool.pop_back();
        placed++;
        if(placed == 21) {
            rep(i, 0, 5) {
                rep(j, 0, 5)
                    cout << grid[j][i] << " ";
                cout << "\n";
            }
            exit(0);
        }
        trav(a, adj)
            dfs(a.f, a.s);
        //unfills
        placed--;
        grid[x][y] = -1;
        pool.pb(pool[i]);
        pool[i] = p;
    }
}

int main() {
    rep(i, 0, 5)
        rep(j, 0, 5)
            grid[i][j] = -1;
    rep(i, 10, 100) {
        bool prime = true;
        rep(j, 2, i) {
            if(i % j == 0) {
                prime = false;
                break;
            }
        }
        if(prime) pool.pb(i);
    }
    dfs(2, 2);
}
