Q=(4.429631392136, 0.7512302308501);
draw(A--B--C--cycle);
draw(Q--X);
draw(Q--Y);
draw(Q--Z);
dot(D);
dot(E);
dot(F);
label(" $A(p,q)$ ",A,N);
label(" $B(0,0)$ ",B,SW);
label(" $C(a,0)$ ",C,SE);
label(" $D\left(\frac{a}{2},0\right)$ ",D,S);
label(" $E\left(\frac{p+a}{2},0\right)$ ",E,NE);
