We claim that Lizzie can guarantee a win if and only if  $n$  is a composite number. 

Let  $a_1,a_2,\ldots ,a_n$  be the numbers Alex picks. 

\begin{lemma2}
    If  $n$  is composite Lizzie can win no matter what numbers Alex picks.
\end{lemma2}

\begin{proof}
    Suppose  $n=pq$  for some positive integers  $p,q<n.$  Lizzie can pick the numbers in groups of  $p$  and replace the numbers in each group by the average of the group., leaving on the blackboard the numbers 
      $$ \overbrace{\frac{\sum\limits_{i=1}^pa_i}{p},\ldots,\frac{\sum\limits_{i=1}^pa_i}{p}}^{\text{ $p$  times}},
    \overbrace{\frac{\sum\limits_{i=p+1}^{2p}a_i}{p},\ldots,\frac{\sum\limits_{i=p+1}^{2p}a_i}{p},}^{\text{ $p$  times}}\ldots,
    \overbrace{\frac{\sum\limits_{i=pq-p+1}^{pq}a_i}{p},\ldots,\frac{\sum\limits_{i=pq-p+1}^{pq}a_i}{p}}^{\text{ $p$  times}}. $$      Then for  $1\leq k\leq p$  she can pick the  $k$ th number in each group (for a total of  $q$  numbers) and replace them each by their average. Each average is equal to
      $$ \frac{1}{q}\sum\limits_{k=1}^q \frac{1}{p}\sum\limits_{i=kp-p+1}^{kp}a_i=\frac{1}{pq}\sum\limits_{i=1}^n a_i, $$      or the average of the original numbers on the blackboard, so the numbers left on the blackboard are equal. 
\end{proof}

\begin{lemma2}
    If  $n$  is prime, at any point in the game there exist constants  $c_{i,j},d_{i,j}\in \mathbb N,\gcd(c_{i,j},d_{i,j})=1,n\nmid d_{i,j}$  for  $1\leq i,j\leq n$  such that  $i$ th number on the blackboard is 
      $$ \sum_{1\leq j\leq n}\frac{c_{i,j}}{d_{i,j}}a_j. $$  \end{lemma2}

\begin{proof}
    We will show this by induction. For the the base case, note that  $(c_{i,j},d_{i,j})=(1,1)$  if  $i=j$ ,  $(0,1)$  if  $i\neq j$  for  $1\leq i,j\leq n$  are such constants for the numbers Alex writes on the blackboard since  $\gcd(1,1)=\gcd(0,1)=1$  and  $n\nmid 1.$  For the inductive step, suppose that at some point in the game such constants  $c_{i,j},d_{i,j}$  for  $1\leq i,j\leq n$  exist and Lizzie replaces the  $i$ th number for all  $i\in S,S\subsetneq \{1,2,\ldots,n\}$  with their average. Consider the constants  ${c_{i,j}}',{d_{i,j}}'\in \mathbb N,\gcd({c_{i,j}}',{d_{i,j}}')=1$  for  $1\leq i,j\leq n$  such that
      $$ \frac{{c_{i,j}}'}{{d_{i,j}}'}=\frac 1{|S|}\sum_{k\in S}\frac{c_{k,j}}{d_{k,j}}\text{ if }i\in S,\frac{c_{i,j}}{\,d_{i,j}}\text{ if } i\notin S. $$   
    Note that after the replacements, the  $i$ th number on the board is 
      $$ \frac 1{|S|}\sum_{k\in S}\sum_{1\leq j\leq n}\frac{c_{k,j}}{d_{k,j}}a_j=\sum_{1\leq j\leq n}\frac 1{|S|}\sum_{k\in S}\frac{c_{k,j}}{d_{k,j}}a_j\text{ if }i\in S,
    \sum_{1\leq j\leq n}\frac{c_{i,j}}{d_{i,j}}a_j\text{ if } i\notin S $$   
      $$ =\sum_{1\leq j\leq n}\frac{{c_{i,j}}'}{{d_{i,j}}'}a_j. $$      For all  $i\in S,1\leq j\leq n$  we have 
    \begin{align*}
        \left(|S|\,{d_{i,j}}'\prod_{l\in S}d_{l,j}\right)\frac{{c_{i,j}}'}{{d_{i,j}}'} &=  \frac 1{|S|}\sum_{k\in S}\frac{c_{k,j}}{d_{k,j}}\left(|S|{d_{i,j}}'\prod_{l\in S}d_{l,j}\right), 
        |S|\,{c_{i,j}}'\prod_{l\in S}d_{l,j} &= {d_{i,j}}'\sum_{k\in S}c_{k,j}\prod\limits_{l\in S,l\neq k}d_{l,j}.
    \end{align*}
    If  $n\mid{c_{i,j}}',$  we have  $n\nmid {d_{i,j}}'$  since  $\gcd({c_{i,j}}',{d_{i,j}}')=1$ , and if  $n\nmid {c_{i,j}}',$  we have 
      $$ |S|<n, n\nmid {c_{i,j}}', n\nmid d_{l,j} \,\forall\, l\in S \implies n\nmid |S|\,{c_{i,j}}'\prod_{l\in S}d_{l,j}\implies n\nmid {d_{i,j}}'. $$      For all  $i\notin S,1\leq j\leq n$  we have  $n\nmid {d_{i,j}}'={d_{i,j}}.$  Hence  $n\nmid {d_{i,j}}'$  for all  $1\leq i,j\leq n$  and such constants exist after Lizzie replaces some of the numbers. It follows by induction that such constants will always exist no matter how many times Lizzie replaces numbers with averages.    
\end{proof}

\begin{lemma2}
    If  $n$  is prime and Alex chooses  $a_1,a_2,\ldots ,a_n$  such that  $n\nmid a_1+a_2+\ldots + a_n,$  Lizzie cannot win.
\end{lemma2}

\begin{proof}
    Note that the sum of the numbers on the blackboard never changes. Therefore, to win the game Lizzie must make all of the numbers equal to the average of the original numbers on the board. Suppose for the sake of contradiction such a state is achieved. Let  $c_{i,j},d_{i,j}$  for  $1\leq i,j\leq n$  be the constants guaranteed by Lemma 2 for the board at this state. Then for all  $1\leq i\leq n$  we have
    \begin{align*}
        \sum_{1\leq j \leq n} \frac{c_{i,j}}{d_{i,j}}a_j &= \frac 1n \sum_{1\leq j\leq n}a_j, 
        n\sum_{1\leq j \leq n} c_{i,j}a_j\prod_{1\leq k\leq n,k\neq j}d_{i,k} &= \sum_{1\leq j\leq n}a_j \prod_{1\leq k\leq n}d_{i,k}, 
        n &\,\Big\lvert \sum_{1\leq j\leq n}a_j \prod_{1\leq k\leq n}d_{i,k}.
        %n\nmid \sum_{1\leq j\leq n}a_j \implies n \mid \prod_{1\leq k\leq n}d_{i,k}& \implies n \mid d_{i,k} \text{ for some  $k$  }, \Rightarrow\!\Leftarrow
    \end{align*}
Since  $n\nmid \sum_{1\leq j\leq n}a_j$ , we must have  $n \mid d_{i,k}$  for some  $k$ , a contradiction.
\end{proof}

It follows from Lemmas 1 and 3 that Lizzie can win no matter what numbers Alex picks if and only if  $n$  is a composite number.  $\hfill\blacksquare$

