    sums.add(grid[0][0]+grid[1][1]+grid[2][2])
    sums.add(grid[2][0]+grid[1][1]+grid[0][2])
    if ((not found1) or (not found2) or len(values)>8 or len(sums)>1):
        return False
    return True

# Function to rotate grid by 90 degrees
def rot90(grid):
    res=deepcopy(grid)
    return list(zip(*res[::-1]))

# Function to reflect the grid
def refl(grid):
    res=deepcopy(grid)
    return [i[::-1] for i in res]

# Convert a grid of lists into a grid of tuples
def convTuple(grid):
    return tuple([tuple(i) for i in grid])

