}


//Solves puzzle by filling row then next column. Return true if puzzle is solvable
bool solve(int grid[][7], int empty)
{
	//Find location of next cell
	int row = (49-empty)/7; //Interger division: quotient
	int col = (48-empty) % 7; //0 -> 6, 1 -> 0, ...


	for(int val = 1; val <= 7; val++)//Loop through choices (may optimize by choosing based on what is left)
	{
		if(checkSquare(grid, row, col, val)) //If valid so far
		{
			if(empty == 1)
				return true; //Base case: if 0 empty and last square fits, solved
			if(solve(grid, empty - 1))
				return true;
		}
		grid[row][col] = val;
		if(checkSquare(grid))
		}
}

void printGrid(int[][7])
{
    for(int r = 0; r < 7; r++)
    {
        for(int c = 0; c < 7; c++)
            std::cout << grid[r][c] << " "
        std::cout << std::endl;
    }
}

//Checks the row, column, and cage conditions for the provided square.
//This checks if the grid is good so far, and only consider triangles once they are complete.
bool checkSquare(int grid[][7], int row, int col, int val)
{
	//Row check - only squares to left
	for(int r = 0; r < row; r++)
		if(grid[r][col] == val)
			return false;

	//Column check - only cells above
	for(int c = 0; c < col; c++)
		if(grid[row][c] == val)
			return false;

	//Check regular triangles
	for(int i = 0; i < 7; i++) //Loop through all 7 cages
	{
		int[] triangle = triangleCages[i];
		//Check only first coordinate
		if(triangle[0][0] == row && triangle[0][1] == col)
			return isTriangle(
			           grid[triangle[0][0]][triangle[0][1]],
			           grid[triangle[1][0]][triangle[1][1]],
			           grid[triangle[2][0]][triangle[2][1]],
			       );
	}

	//Check acute triangles
	for(int i = 0; i < 3; i++) //Loop through all 3 cages
	{
		int[] triangle = acuteCages[i];
		//Check only first coordinate
		if(triangle[0][0] == row && triangle[0][1] == col)
			return isAcute(
			           grid[triangle[0][0]][triangle[0][1]],
			           grid[triangle[1][0]][triangle[1][1]],
			           grid[triangle[2][0]][triangle[2][1]],
			       );
	}

	//Check for right
	for(int i = 0; i < 3; i++) //Loop through all 3 cages
	{
		int[] triangle = rightCages[i];
		//Check only first coordinate
		if(triangle[0][0] == row && triangle[0][1] == col)
			return isRight(
			           grid[triangle[0][0]][triangle[0][1]],
			           grid[triangle[1][0]][triangle[1][1]],
			           grid[triangle[2][0]][triangle[2][1]],
			       );
	}

	return true; //If not the end of a cage and not violating row/column, then true
}

//Swaps the value of a and b
void swap(int& a, int& b)
{
	int temp = a;
	a = b;
	b = temp;
}

//Takes in a, b, c and orders so a is max (b and c are not ordered)
void order(int& a, int& b, int& c)
{
	if (c > b)
		swap(b, c);
	if(b > a)
		swap(a, b);
}

//Checks whether triangle with side lengths a, b, and c is right
//Brute force check all permutations for 3, 4, 5 -- DONE
bool isRight(int a, int b, int c)
{
	order(a, b, c);
	//We could check for a, b, c = 5, 4, 3 or 5, 3, 4
	return (a*a == b*b + c*c);
}

bool isTriangle(int a, int b, int c)
{
	order(a, b, c);
	return a < b + c;
}

bool isAcute(int a, int b, int c)
{
	order(a, b, c);
	return a*a < b*b + c*c;
}

