I claim that for nonnegative  $m, n$  we have that  $\sqrt{m + n + \sqrt{4mn}} = \sqrt{m} + \sqrt{n}.$  
\begin{proof}
The left hand side is equivalent to:
    \begin{align*}
        \sqrt{m + n + \sqrt{4mn}} & = \sqrt{(\sqrt m)^2 + 2\sqrt{m}\sqrt n + (\sqrt n)^2} 
        & = \sqrt{(\sqrt m + \sqrt n)^2} 
        & = |\sqrt{m} + \sqrt n| = \sqrt m + \sqrt n
    \end{align*}
\end{proof}

I claim that if  $m \geq n \geq 0,$  then  $\sqrt{m + n - \sqrt{4mn}} = \sqrt{m} - \sqrt{n}.$  
\begin{proof}
The left hand side is equivalent to:
    \begin{align*}
        \sqrt{m + n - \sqrt{4mn}} & = \sqrt{(\sqrt m)^2 - 2\sqrt{m}\sqrt n + (\sqrt n)^2} 
        & = \sqrt{(\sqrt m - \sqrt n)^2} 
        & = |\sqrt{m} - \sqrt n| = \sqrt m - \sqrt n
    \end{align*}
\end{proof}
\begin{enumerate}
    \item Take  $b = 4a - 4 \leq a^2$  where the inequality is true by trivial inequality(equality holds at  $x = 2$ ). Furthermore,  $b > 0$  since  $a \geq2.$  Hence, 
    \begin{align*}
        x = \sqrt{a + \sqrt{4a - 4}} - \sqrt{a - \sqrt{4a - 4}} & = \sqrt{a - 1 + 1 + \sqrt{4(a - 1)1}} - \sqrt{a - 1 + 1- \sqrt{4(a -1)1}} 
        & = \sqrt{a - 1} + 1 - (\sqrt{a - 1} - 1) \text{ by our two claims and }a \geq 2
        & = 2
    \end{align*}
    \item I claim that for  $a \geq 1434,$  we must have that  $b = 16(a - 4)$  is another solution. Obviously,  $16(a - 4) \neq 4a - 4.$  We also have that  $b\geq1$  and  $b\leq a^2$ , which follows from  
    \begin{align*}
        x = \sqrt{a + \sqrt{16(a - 4)}} - \sqrt{a - \sqrt{16(a - 4)}} & = \sqrt{a - 4 + 4 + \sqrt{4(a - 4)4}} - \sqrt{a - 4 + 4 - \sqrt{4(a -4)4}} 
        & = \sqrt{a - 4} + 2 - (\sqrt{a - 4} - 2) \text{ by our two claims and }a \geq 1434
        & = 4
    \end{align*}
    Therefore, for sufficiently large  $a,$  there exists at least two positive integer values of  $b$  such that  $x$  is a positive integer. 
