	draw((0,j)--(width,j));
}
for(int i =0; i<width; ++i) {
	draw((i,0)--(i,1), royalblue+linewidth(4));
    draw((width-i,height)--(width-i,height-1), royalblue+linewidth(4));
}
for(int i =0; i<height; ++i) {
	draw((0,i+1)--(1,i+1), royalblue+linewidth(4));
