int cols = 5;
real margin = 0.1;

// Draw grid
for (int i = 0; i <= rows; ++i)
  draw((0,i)--(cols,i));
for (int j = 0; j <= cols; ++j)
  draw((j,0)--(j,rows));

// Draw surrounding red rectangle (slightly larger)
draw((0 - margin, 0 - margin)--(cols + margin, 0 - margin)--(cols + margin, rows + margin)--
     (0 - margin, rows + margin)--cycle, red);

// Draw blue rectangles in even-numbered rows (rows 0 and 2)
for (int r = 0; r < rows; ++r) {
  if (r % 2 == 0) {
    pair bl = (0 + margin, r + margin);
    pair tr = (cols - margin, r + 1 - margin);
    draw(bl--(tr.x, bl.y)--tr--(bl.x, tr.y)--cycle, blue);
  }
}

// Draw two green rectangles in 2nd and 4th columns, spanning full height
real greenMargin = 2 * margin;
int[] greenCols = {1, 3};
for (int j : greenCols) {
  pair gbl = (j + greenMargin, 0 + greenMargin);
  pair gtr = (j + 1 - greenMargin, rows - greenMargin);
  draw(gbl--(gtr.x, gbl.y)--gtr--(gbl.x, gtr.y)--cycle, green);
}

// Label lengths m (horizontal) and n (vertical)
