\overline{p} &= \frac{\frac{1}{ac}\left(\frac{1}{b}+\frac{1}{d} \right) - \frac{1}{bd}\left(\frac{1}{a}+\frac{1}{c} \right)}{\frac{1}{ac}-\frac{1}{bd}}
&= \frac{a-b-c+d}{ac-bd}
\end{align*}
Then, 
\begin{align*}
e &= \frac{1}{2}\left( p+a+b-ab\overline{p} \right)
&= \frac{abc+acd-bcd-abd+a^2c-a^2b+ab^2-b^2d}{2(ac-bd)}
\end{align*}
Similarly, 
\[f = \frac{abc+acd-bcd-abd+ac^2-c^2d+cd^2-bd^2}{2(ac-bd)}\]
Then, let  $M_1,M_2$  be the midpoints of  $AD$  and  $BC$ . This gives, 
\[m_1=\frac{a+d}{2} \text{ and } m_2=\frac{b+c}{2}\]
Then, we observe that, 
\begin{align*}
\frac{m_1-m_2}{e-f} &= \frac{\frac{a-b-c+d}{2}}{\frac{abc+acd-bcd-abd+a^2c-a^2b+ab^2-b^2d-(abc+acd-bcd-abd+ac^2-c^2d+cd^2-bd^2)}{2(ac-bd)}}
&= \frac{(a-b-c+d)(ac-bd)}{(a-b-c+d)(ac+bd-ab-cd)}
&= \frac{ac-bd}{ac+bd-ab-cd}
\end{align*}
We can then see that, 
