Complex on  $(AHPQ)=\omega $  and set  $Q=y, P=z, A=w, H=x$  in complex numbers
    Denote  $G$  on  $\omega$  such that  $HG\perp AZ$ ,  $J$  on  $\omega $  such that  $HJ\perp AY$      $G=-wz/y, J=-wy/x$      $B=XG\cap YW=\frac{wy(x-wz/x)+wz(w+y)}{wy+wz}$      $=\frac{x^2y-wyz+wxz+xyz}{x(y+z)}$     Similarly,  $C=HJ\cap AZ=\frac{x^2z-wyz+wxy+xyz}{x(y+z)}$      $R$   lies on  $OPQ$  thus  $\frac{(R-y)z}{(R-z)y}\in \mathbb{R}$      $\iff \frac{(R-y)z}{(R-z)y}=\frac{\overline{R}y-1}{\overline{R}z-1}$      $\iff (Rz-yz)(\overline{R}z-1)=(Ry-yz)(\overline{R}y-1)$      $\iff R\overline{R}(z^2-y^2)+(y^2z-yz^2)\overline{R}+Ry-Rz=0$      $\iff R\overline{R}(z+y)=R+yz\overline{R}$      $\implies \boxed{\frac{yz\overline{R}}{\overline{R}(y+z)-1}}$      $\overline{RBC}\iff (R-C)/(B-C)\in\mathbb{R}$      $\iff \frac{x(y+z)R-(x^2z-wyz+wxy+xyz)}{(z-y)x(x-w)}\in\mathbb{R}$      $x(y+z))R-(x^2z-wyz+wxy+xyz)=x^2w(y+z)\overline{R}-(wxy-x^3+x^2z+x^2w)$      $\iff x^3-x^2w-wyz=xyz+x^2w(y+z)\overline{R}=x(y+z)R=\frac{xyz(y+z)\overline{R}}{\overline{R}(y+z)-1}$      $\iff xyz(y+z)\overline{R}=x^2w(y+z)^2\overline{R}^2+((y+z)(x-w)(x^2+yz)-x^2w(y+z))\overline{R}+(w-x)(x^2+yz)$      $\iff \boxed{x^2w(y+z)^2\overline{R}^2+(y+z)(x^3-2x^2w-wyz)\overline{R}+(w-x)(x^2+yz)=0}$     Since there is only 1 value of  $R$ , we must have  $b^2=4ac$ (quadratic in  $\overline{R}$ )
     $\iff (x^3-2x^w-wyz)^2=4x^2w(w-x)(x^2+yz)$      $\iff x^6+4x^2w^2+w^2y^2z^2-4x^5w-2x^3wyz+4x^2w^2yz=4x^4w^2+4w^2x^2yz-4x^5w-4x^3wyz$      $\iff x^6+w^2y^2z^2+2x^3wyz=0$      $\iff \boxed{(x^3+wyz)^2=0}$      $\overline{R}=\frac{2x^2w+wyz-x^3}{2x^2w(y+z)}$      $\boxed{R=\frac{2xyz+x^3-wyz}{2x(y+z)}}$ \begin{align*}
    \frac{ED}{FD}&=\frac{sinccosc}{sinbcosb}\text{ (by trig)}
    &=|\frac{AE\cdot HE}{HF\cdot EF}|
    &=|\frac{(w-w/2-z/2-x/2+wz/2x)(x-w/2-z/2-x/2+wz/2x)}{(w-w/2-y/2-x/2+wy/2x)(x-w/2-y/2-x/2+wy/2x)}|
    &=|\frac{(xw-xz-x^2+wz)(x^2-xw-xz+wz)}{(xw-xy-x^2+wy)(x^2-xw-xy+wy)}|
    &=|\frac{(x-w)(-x-z)(x-w)(x-z)}{(x-w)(-x-y)(x-w)(x-y)}|
    &=|\frac{x^2-z^2}{x^2-y^2}|
    &=\frac{-(x^2-z^2)y}{(x^2-y^2)z}
\end{align*}
   Then, 
\begin{align*}
|\frac{CR}{BR}|&=\frac{C-R}{B-R}
    &=\frac{\frac{2x^2z-wyz+2wxy-x^3}{2x(y+z)}}{\frac{x^3+wyz-2x^2y-2wxz}{2x(y+z)}}
    &=\frac{2x^2z+2wxy}{-2x^2y-2wxz}\text{ (using the fact that  $x^3+wyz=0$ )}
    &=\frac{xz+wy}{-(xy+wz)}
    &=\frac{-(xz-x^3/z)}{xy-x^3/y}
    &=\frac{-(x^2-z^2)y}{(x^2-y^2)z}
\end{align*}
As desired

