        draw(omega);

        draw(A -- B ^^ C -- D);
        draw(circumcircle(A, D, X));
        draw(circumcircle(B, C, Y));
        draw(X -- Y);

        pair W = 2 * foot(circumcenter(B, C, Y), A, B) - B; 
        pair Z = 2 * foot(circumcenter(A, D, X), C, D) - D; 
        pair R = 2 * foot(circumcenter(A, D, X), W, Z) - Z; 
        pair S = 2 * foot(circumcenter(B, C, Y), W, Z) - W; 

        draw(W -- Z);
