        pair Z = 2 * foot(circumcenter(A, D, X), C, D) - D; 
        pair R = 2 * foot(circumcenter(A, D, X), W, Z) - Z; 
        pair S = 2 * foot(circumcenter(B, C, Y), W, Z) - W; 

        draw(W -- Z, green);
        draw(circumcircle(P, Q, R), red+dashed);

        dot(" $A$ ", A, A);
        dot(" $B$ ", B, B);
        dot(" $C$ ", C, C);
