}

void dottedrect(real l, real r, real b, real t) {
l += eps;
r -= eps;
b += eps;
t -= eps;
draw((l, b) -- (l, t) -- (r, t) -- (r, b) -- cycle, dashed);
}

rect(5-eps,3+eps,5-eps,3,red);
rect(2-eps,3+eps,5-eps,3,blue);
rect(0-eps,2+eps,5-eps,1+eps,orange);
rect(0-eps,2+eps,1-eps,0+eps,green);

dottedrect(0-eps,1+eps,5-eps,0+eps);
dottedrect(0-eps,5+eps,5-eps,4+eps);

